mapper.select:
SELECT id, user_id, content, title, clarified_content, status, 
       final_type, confidence, starred, error_message, create_time, update_time
FROM almond_item
WHERE user_id = #{userId}

    AND status = #{status}


    AND final_type = #{finalType}


    AND starred = #{starred}


    AND (title LIKE CONCAT('%', #{keyword}, '%') 
         OR content LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY

    update_time
    create_time


    ASC
    DESC

LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM almond_item
WHERE user_id = #{userId}

    AND status = #{status}


    AND final_type = #{finalType}


    AND starred = #{starred}


    AND (title LIKE CONCAT('%', #{keyword}, '%') 
         OR content LIKE CONCAT('%', #{keyword}, '%'))
